/*
 * A057096  Saint-Exupéry numbers: ordered products of the three sides of
 *          Pythagorean triangles.
 * https://oeis.org/A057096
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the product a*b*c of the sides of the nth smallest
 *            Pythagorean triple sorted by product. (0‑based array indexing
 *            used internally). The sequence is generated by enumerating all
 *            primitive triples (m,n) and then producing all integer multiples
 *            of those primitives in ascending order of product...
 * Range:     u8 none, u16 none, u32 n <= 11, u64 n <= 10000, u128 n <= 10000,
 *            big any n
 * Helpers:   gcd_u64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/gcd_u64.h"

/* The build supplies the types 'seq_t' and 'idx_t' */
static void init_primitives(void);
static seq_t next_term(void);

/* -------------------------------------------------------------------------- */
/* Utility: gcd for 64‑bit unsigned integers */

/* -------------------------------------------------------------------------- */
/* Primitive triple product list and heap structures */
struct HeapNode {
    seq_t val;          /* current product for this primitive * k³ */
    size_t prim_idx;    /* index of primitive */
    uint32_t k;         /* current multiplier */
};

static seq_t *prim_prod = NULL;      /* array of primitive products */
static size_t prim_count = 0;         /* number of primitives */
static struct HeapNode *heap = NULL;  /* binary min‑heap */
static size_t heap_size = 0;

/* ----------------- heap operations --------------------------------------- */
static inline void heap_swap(size_t i, size_t j)
{
    struct HeapNode tmp = heap[i];
    heap[i] = heap[j];
    heap[j] = tmp;
}

static void heap_push(struct HeapNode node)
{
    size_t i = heap_size++;
    heap[i] = node;
    /* sift up */
    while (i > 0) {
        size_t parent = (i - 1) >> 1;
        if (heap[parent].val <= heap[i].val) break;
        heap_swap(i, parent);
        i = parent;
    }
}

static struct HeapNode heap_pop(void)
{
    struct HeapNode top = heap[0];
    heap[0] = heap[--heap_size];
    /* sift down */
    size_t i = 0;
    while (true) {
        size_t left = (i << 1) + 1;
        if (left >= heap_size) break;
        size_t right = left + 1;
        size_t smallest = left;
        if (right < heap_size && heap[right].val < heap[left].val)
            smallest = right;
        if (heap[i].val <= heap[smallest].val) break;
        heap_swap(i, smallest);
        i = smallest;
    }
    return top;
}

/* -------------------------------------------------------------------------- */
/* Build all primitive triple products (m,n) with m < M */
#define MAX_M 2000  /* chosen to comfortably cover 10 000 terms */

static void init_primitives(void)
{
    /* First count primitives to allocate array */
    size_t count = 0;
    for (uint32_t m = 2; m <= MAX_M; ++m) {
        for (uint32_t n = 1; n < m; ++n) {
            if (((m - n) & 1) == 0) continue;          /* both odd or both even */
            if (gcd_u64(m, n) != 1) continue;           /* not coprime */
            count++;
        }
    }
    prim_count = count;
    prim_prod = (seq_t *)malloc(prim_count * sizeof(seq_t));
    heap = (struct HeapNode *)malloc(prim_count * sizeof(struct HeapNode));

    /* Generate primitives */
    size_t idx = 0;
    for (uint32_t m = 2; m <= MAX_M; ++m) {
        for (uint32_t n = 1; n < m; ++n) {
            if (((m - n) & 1) == 0) continue;
            if (gcd_u64(m, n) != 1) continue;
            seq_t a = (seq_t)(m * m) - (seq_t)(n * n);
            seq_t b = (seq_t)2 * (seq_t)m * (seq_t)n;
            seq_t c = (seq_t)(m * m) + (seq_t)(n * n);
            seq_t prod = a * b * c;
            prim_prod[idx] = prod;
            /* initial heap node with k = 1 */
            heap[idx].val = prod;          /* prod * 1³ */
            heap[idx].prim_idx = idx;
            heap[idx].k = 1;
            idx++;
        }
    }

    /* Build min‑heap */
    for (size_t i = (heap_size = prim_count); i --> 0;) {
        size_t left = (i << 1) + 1;
        if (left >= heap_size) continue;
        size_t right = left + 1;
        size_t smallest = left;
        if (right < heap_size && heap[right].val < heap[left].val)
            smallest = right;
        if (heap[i].val <= heap[smallest].val) continue;
        heap_swap(i, smallest);
    }
}

/* -------------------------------------------------------------------------- */
/* Cache for already computed sequence values */
struct SeqCache {
    seq_t *data;     /* array of values (0‑based) */
    size_t len;      /* number of values stored */
    size_t cap;      /* allocated capacity */
};
static struct SeqCache cache = {NULL, 0, 0};
static seq_t last_output = 0;      /* last value output to check duplicates */

/* -------------------------------------------------------------------------- */
/* Generate the next unique term from the heap */
static seq_t next_term(void)
{
    while (true) {
        struct HeapNode node = heap_pop();
        seq_t val = node.val;
        /* push next multiple for this primitive */
        uint32_t next_k = node.k + 1;
        seq_t k_cube = (seq_t)next_k * (seq_t)next_k * (seq_t)next_k;
        seq_t new_val = prim_prod[node.prim_idx] * k_cube;
        heap_push((struct HeapNode){new_val, node.prim_idx, next_k});

        if (cache.len == 0 || val != last_output) {
            /* store it */
            if (cache.len == cache.cap) {
                size_t new_cap = cache.cap ? cache.cap * 2 : 64;
                seq_t *tmp = (seq_t *)realloc(cache.data, new_cap * sizeof(seq_t));
                cache.data = tmp;
                cache.cap = new_cap;
            }
            cache.data[cache.len++] = val;
            last_output = val;
            return val;
        }
        /* else duplicate, skip */
    }
}

/* -------------------------------------------------------------------------- */
/* Main sequence function requested by the challenge */
seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* undefined, return 0 */
    if (prim_prod == NULL) init_primitives();   /* one‑time initialization */

    /* generate terms until we have at least n */
    while (cache.len < (size_t)n) {
        (void)next_term();
    }
    return cache.data[(size_t)n - 1];
}
